add_filter( 'woocommerce_cart_item_name', 'perfectpixel_categories_under_cart_item', 30, 3 );

function perfectpixel_categories_under_cart_item( $name, $cart_item, $cart_item_key ) {
	$product_id = (int) ( $cart_item['product_id'] ?? 0 );
	if ( ! $product_id ) {
		return $name;
	}
	$list = wc_get_product_category_list( $product_id, ', ' );
	if ( '' === (string) $list ) {
		return $name;
	}
	return $name . '<div class="perfectpixel-cart-categories" style="font-size:.85em;opacity:.8">' . esc_html( '{{categories_label}}' ) . ' ' . wp_strip_all_tags( $list ) . '</div>';
}
